$Root=(Resolve-Path (Join-Path $PSScriptRoot '..')).Path;$Checks=[ordered]@{Python=!!(Get-Command python -ErrorAction SilentlyContinue);Node=!!(Get-Command node -ErrorAction SilentlyContinue);FFprobe=!!(Get-Command ffprobe -ErrorAction SilentlyContinue);Config=Test-Path (Join-Path $Root '.env.local');Database=Test-Path (Join-Path $Root 'data\shop-live.db');DashboardBuild=Test-Path (Join-Path $Root '..\dashboard\dist\index.html')}
$Checks|ConvertTo-Json;try{$Response=Invoke-WebRequest -UseBasicParsing -Uri 'http://127.0.0.1:8765/shop-live/v1/health' -TimeoutSec 2;Write-Host "Agente HTTP: $($Response.StatusCode)"}catch{Write-Host 'Agente HTTP: protegido, parado ou indisponivel (esperado sem token)'}
